import { WritableLike } from '..';

declare namespace stream {
    export interface QloudStreamOptions {
        /** Fields to exclude from log record */
        excludeFields?: string[];

        /** Any writable stream (process.stdout by default) */
        stream?: WritableLike;
    }
}

/**
 * Qloud compatible stream
 */
declare function stream(config?: stream.QloudStreamOptions): WritableLike;

export = stream;
